                {publicStats.value.streak !== undefined && (
                  <span>
                    {publicStats.value.streakKind === "longest"
                      ? "longest"
                      : "current"}{" "}
                    streak: {publicStats.value.streak}{" "}
                    {publicStats.value.streak === 1 ? "day" : "days"}
                    {publicStats.value.streakTruncated ? " or more" : ""}
                  </span>
